					break;
				}
			}
		},
		rejectHunk: async (proposalId: string, hunkId: string) => {
			for (const [, state] of sessions) {
				if (state.review.getProposal(proposalId)) {
					await state.review.rejectHunk(proposalId, hunkId);
					break;
				}
			}
		},
		acceptFile: async (proposalId: string) => {
			for (const [, state] of sessions) {
